#!/usr/bin/env python3
"""Queen five-entry per-thread alias cache after retained FEX overlays.
No frame layout/ABI change. Fresh process required, not a live patch.
"""
import sys
from pathlib import Path
r=Path(sys.argv[1]);p=r/'Source/Windows/ARM64EC/Module.S'
a=(r/'Source/Windows/ARM64EC/IosJitAlias.cpp').read_text()
assert 'constexpr int kMaxEntries = 1024;' in a, 'Apply retained capacity overlay first'
s=p.read_text()
old='  ldr x16, [x28, #IOS_FRAME_ALIAS_HINT]\n  cbz x16, ios_ec_jit_xlate_walk\n  ldr x23, [x16]        // Entry.PeBase\n  sub x23, x9, x23\n  ldr x4, [x16, #16]    // Entry.Size\n  cmp x23, x4\n  b.lo ios_ec_xlate_hit\nios_ec_jit_xlate_walk:\n  adrp x17, IosAliasCount\n  ldr w17, [x17, #:lo12:IosAliasCount]\n  adrp x16, IosAliasEntries\n  add x16, x16, #:lo12:IosAliasEntries\n  add x16, x16, x17, lsl #5   // one past the last entry\nios_ec_jit_xlate_loop:\n  cbz w17, ios_ec_xlate_done\n  sub x16, x16, #32\n  sub w17, w17, #1\n  ldr x23, [x16]        // Entry.PeBase\n  sub x23, x9, x23\n  ldr x4, [x16, #16]    // Entry.Size\n  cmp x23, x4\n  b.hs ios_ec_jit_xlate_loop\n  str x16, [x28, #IOS_FRAME_ALIAS_HINT]\n  b ios_ec_xlate_hit'
new='  // Five 12-bit 1-based indices in existing 64-bit hint, MRU first.\n  // Low60 bits only; storage bound1024 matches alias-capacity-v1.\n  // Fresh frames start at zero. Live entry ranges are rechecked every hit.\n  ldr x16, [x28, #IOS_FRAME_ALIAS_HINT]\n  ubfx x16, x16, #0, #12\n  cbz w16, ios_ec_jit_hint_slot1\n  cmp w16, #1024\n  b.hi ios_ec_jit_hint_slot1\n  adrp x17, IosAliasCount\n  ldr w4, [x17, #:lo12:IosAliasCount]\n  cmp w4, #1024\n  b.hi ios_ec_xlate_done\n  cmp w16, w4\n  b.hi ios_ec_jit_hint_slot1\n  adrp x17, IosAliasEntries\n  add x17, x17, #:lo12:IosAliasEntries\n  sub w16, w16, #1\n  add x16, x17, x16, lsl #5\n  ldr x23, [x16]\n  sub x23, x9, x23\n  ldr x4, [x16, #16]\n  cmp x23, x4\n  b.lo ios_ec_xlate_hit\n\nios_ec_jit_hint_slot1:\n  ldr x16, [x28, #IOS_FRAME_ALIAS_HINT]\n  ubfx x16, x16, #12, #12\n  cbz w16, ios_ec_jit_hint_slot2\n  cmp w16, #1024\n  b.hi ios_ec_jit_hint_slot2\n  adrp x17, IosAliasCount\n  ldr w4, [x17, #:lo12:IosAliasCount]\n  cmp w4, #1024\n  b.hi ios_ec_xlate_done\n  cmp w16, w4\n  b.hi ios_ec_jit_hint_slot2\n  adrp x17, IosAliasEntries\n  add x17, x17, #:lo12:IosAliasEntries\n  sub w16, w16, #1\n  add x16, x17, x16, lsl #5\n  ldr x23, [x16]\n  sub x23, x9, x23\n  ldr x4, [x16, #16]\n  cmp x23, x4\n  b.hs ios_ec_jit_hint_slot2\n  // BFI reads its old source before writing destination, even when identical.\n  ldr x4, [x28, #IOS_FRAME_ALIAS_HINT]\n  ubfx x17, x4, #12, #12\n  bfi x4, x4, #12, #12\n  bfi x4, x17, #0, #12\n  and x4, x4, #0x0fffffffffffffff\n  str x4, [x28, #IOS_FRAME_ALIAS_HINT]\n  b ios_ec_xlate_hit\n\nios_ec_jit_hint_slot2:\n  ldr x16, [x28, #IOS_FRAME_ALIAS_HINT]\n  ubfx x16, x16, #24, #12\n  cbz w16, ios_ec_jit_hint_slot3\n  cmp w16, #1024\n  b.hi ios_ec_jit_hint_slot3\n  adrp x17, IosAliasCount\n  ldr w4, [x17, #:lo12:IosAliasCount]\n  cmp w4, #1024\n  b.hi ios_ec_xlate_done\n  cmp w16, w4\n  b.hi ios_ec_jit_hint_slot3\n  adrp x17, IosAliasEntries\n  add x17, x17, #:lo12:IosAliasEntries\n  sub w16, w16, #1\n  add x16, x17, x16, lsl #5\n  ldr x23, [x16]\n  sub x23, x9, x23\n  ldr x4, [x16, #16]\n  cmp x23, x4\n  b.hs ios_ec_jit_hint_slot3\n  // BFI reads its old source before writing destination, even when identical.\n  ldr x4, [x28, #IOS_FRAME_ALIAS_HINT]\n  ubfx x17, x4, #24, #12\n  bfi x4, x4, #12, #24\n  bfi x4, x17, #0, #12\n  and x4, x4, #0x0fffffffffffffff\n  str x4, [x28, #IOS_FRAME_ALIAS_HINT]\n  b ios_ec_xlate_hit\n\nios_ec_jit_hint_slot3:\n  ldr x16, [x28, #IOS_FRAME_ALIAS_HINT]\n  ubfx x16, x16, #36, #12\n  cbz w16, ios_ec_jit_hint_slot4\n  cmp w16, #1024\n  b.hi ios_ec_jit_hint_slot4\n  adrp x17, IosAliasCount\n  ldr w4, [x17, #:lo12:IosAliasCount]\n  cmp w4, #1024\n  b.hi ios_ec_xlate_done\n  cmp w16, w4\n  b.hi ios_ec_jit_hint_slot4\n  adrp x17, IosAliasEntries\n  add x17, x17, #:lo12:IosAliasEntries\n  sub w16, w16, #1\n  add x16, x17, x16, lsl #5\n  ldr x23, [x16]\n  sub x23, x9, x23\n  ldr x4, [x16, #16]\n  cmp x23, x4\n  b.hs ios_ec_jit_hint_slot4\n  // BFI reads its old source before writing destination, even when identical.\n  ldr x4, [x28, #IOS_FRAME_ALIAS_HINT]\n  ubfx x17, x4, #36, #12\n  bfi x4, x4, #12, #36\n  bfi x4, x17, #0, #12\n  and x4, x4, #0x0fffffffffffffff\n  str x4, [x28, #IOS_FRAME_ALIAS_HINT]\n  b ios_ec_xlate_hit\n\nios_ec_jit_hint_slot4:\n  ldr x16, [x28, #IOS_FRAME_ALIAS_HINT]\n  ubfx x16, x16, #48, #12\n  cbz w16, ios_ec_jit_xlate_walk\n  cmp w16, #1024\n  b.hi ios_ec_jit_xlate_walk\n  adrp x17, IosAliasCount\n  ldr w4, [x17, #:lo12:IosAliasCount]\n  cmp w4, #1024\n  b.hi ios_ec_xlate_done\n  cmp w16, w4\n  b.hi ios_ec_jit_xlate_walk\n  adrp x17, IosAliasEntries\n  add x17, x17, #:lo12:IosAliasEntries\n  sub w16, w16, #1\n  add x16, x17, x16, lsl #5\n  ldr x23, [x16]\n  sub x23, x9, x23\n  ldr x4, [x16, #16]\n  cmp x23, x4\n  b.hs ios_ec_jit_xlate_walk\n  // BFI reads its old source before writing destination, even when identical.\n  ldr x4, [x28, #IOS_FRAME_ALIAS_HINT]\n  ubfx x17, x4, #48, #12\n  bfi x4, x4, #12, #48\n  bfi x4, x17, #0, #12\n  and x4, x4, #0x0fffffffffffffff\n  str x4, [x28, #IOS_FRAME_ALIAS_HINT]\n  b ios_ec_xlate_hit\n\nios_ec_jit_xlate_walk:\n  adrp x17, IosAliasCount\n  ldr w17, [x17, #:lo12:IosAliasCount]\n  cmp w17, #1024\n  b.hi ios_ec_xlate_done\n  adrp x16, IosAliasEntries\n  add x16, x16, #:lo12:IosAliasEntries\n  add x16, x16, x17, lsl #5\nios_ec_jit_xlate_loop:\n  cbz w17, ios_ec_xlate_done\n  sub x16, x16, #32\n  sub w17, w17, #1\n  ldr x23, [x16]\n  sub x23, x9, x23\n  ldr x4, [x16, #16]\n  cmp x23, x4\n  b.hs ios_ec_jit_xlate_loop\n  add w17, w17, #1\n  ldr x4, [x28, #IOS_FRAME_ALIAS_HINT]\n  orr x17, x17, x4, lsl #12\n  and x17, x17, #0x0fffffffffffffff\n  str x17, [x28, #IOS_FRAME_ALIAS_HINT]\n  b ios_ec_xlate_hit'
assert s.count(old)==1,'Unexpected lean-exit assembly; refuse patch drift'
p.write_text(s.replace(old,new))
print('Applied Queen five-entry alias hint; no other code/frame layout changed')

